{
  "versions": [
    {
      "label": "1",
      "angle": "从旅行收纳与日常外观选择切入，再讲便携打理、静音防滑，最后回到足弓支撑与厚底缓震",
      "blocks": [
        {
          "stage": "welcome",
          "focus": "开场互动",
          "sentences": [
            {
              "display_text": "欢迎来到直播间，今天咱们看一双出门在家都能穿的凉拖鞋。",
              "spoken_text": "欢迎来到直播间，今天咱们看一双出门在家都能穿的凉拖鞋。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "姐妹平时收拾行李，会不会纠结带哪双鞋？",
              "spoken_text": "姐妹平时收拾行李，会不会纠结带哪双鞋？",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "pain",
          "focus": "旅行带鞋的收纳困扰",
          "sentences": [
            {
              "display_text": "出门玩想穿得轻松，又怕鞋占地方、弄脏行李箱。",
              "spoken_text": "出门玩想穿得轻松，又怕鞋占地方、弄脏行李箱。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "住酒店时想换自己的拖鞋，又希望它不吵到同住的人。",
              "spoken_text": "住酒店时想换自己的拖鞋，又希望它不吵到同住的人。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "identity",
          "focus": "商品身份与整体印象",
          "sentences": [
            {
              "display_text": "这双是足弓支撑静音防滑厚底凉拖鞋，小蛮腰女款。",
              "spoken_text": "这双是足弓支撑静音防滑厚底凉拖鞋，小蛮腰女款。",
              "kind": "product_claim",
              "fact_ids": ["NAME"]
            },
            {
              "display_text": "厚底平底、一般版型，居家休闲或者旅行出游都合适。",
              "spoken_text": "厚底平底、一般版型，居家休闲或者旅行出游都合适。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "轻便耐磨与旅行携带",
          "sentences": [
            {
              "display_text": "这双鞋轻便耐磨，塞进行李箱不会占太多空间。",
              "spoken_text": "这双鞋轻便耐磨，塞进行李箱不会占太多空间。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "去海边漫步、出门散步、下楼倒垃圾，穿着它走一段路也比较轻松。",
              "spoken_text": "去海边漫步、出门散步、下楼倒垃圾，穿着它走一段路也比较轻松。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "快干防臭与清洗打理",
          "sentences": [
            {
              "display_text": "材质防臭快干，一冲即净，洗澡出来鞋面沾了水，冲一冲、晾一晾，下回穿也清爽。",
              "spoken_text": "材质防臭快干，一冲即净，洗澡出来鞋面沾了水，冲一冲、晾一晾，下回穿也清爽。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "它是一体成型的优选 E V A 环保材质，没有多余拼接，打理起来省事。",
              "spoken_text": "它是一体成型的优选 E V A 环保材质，没有多余拼接，打理起来省事。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "静音防滑与居家走动",
          "sentences": [
            {
              "display_text": "鞋底具备静音与防滑特性，晚上在浴室或室内走动，能减少打扰家人。",
              "spoken_text": "鞋底具备静音与防滑特性，晚上在浴室或室内走动，能减少打扰家人。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "湿地面行走时自己多留神，但它在居家和浴室这些场景里，确实考虑到了安静和抓地。",
              "spoken_text": "湿地面行走时自己多留神，但它在居家和浴室这些场景里，确实考虑到了安静和抓地。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "足弓支撑与厚底缓震",
          "sentences": [
            {
              "display_text": "再看脚底这一块，它有足弓支撑，不是完全平铺的鞋床。",
              "spoken_text": "再看脚底这一块，它有足弓支撑，不是完全平铺的鞋床。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "你在家站着切菜、叠衣服，脚心有一个承托的位置，久站会舒服一些。",
              "spoken_text": "你在家站着切菜、叠衣服，脚心有一个承托的位置，久站会舒服一些。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "配合小蛮腰厚底和软弹缓震，踩下去有一点回弹感，从脚底到小腿都松快一点。",
              "spoken_text": "配合小蛮腰厚底和软弹缓震，踩下去有一点回弹感，从脚底到小腿都松快一点。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "specification",
          "focus": "颜色尺码与选码建议",
          "sentences": [
            {
              "display_text": "颜色有粉色、蓝色、黑色、白色、卡其等，一共十个颜色可选。",
              "spoken_text": "颜色有粉色、蓝色、黑色、白色、卡其等，一共十个颜色可选。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "尺码从三十六码到四十五码，分三十六到三十七、三十八到三十九、四十到四十一、四十二到四十三、四十四到四十五。",
              "spoken_text": "尺码从三十六码到四十五码，分三十六到三十七、三十八到三十九、四十到四十一、四十二到四十三、四十四到四十五。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "标准码，脚背较宽或脚型偏肉，建议斟酌大一号。",
              "spoken_text": "标准码，脚背较宽或脚型偏肉，建议斟酌大一号。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "price",
          "focus": "准确价格",
          "sentences": [
            {
              "display_text": "价格方面，原价一百七十八新台币。",
              "spoken_text": "价格方面，原价一百七十八新台币。",
              "kind": "product_claim",
              "fact_ids": ["PRICE"]
            },
            {
              "display_text": "活动价一百零七新台币。",
              "spoken_text": "活动价一百零七新台币。",
              "kind": "product_claim",
              "fact_ids": ["PRICE"]
            }
          ]
        },
        {
          "stage": "promotion",
          "focus": "优惠条件",
          "sentences": [
            {
              "display_text": "原价一百七十八新台币，限时下杀一百零七新台币。",
              "spoken_text": "原价一百七十八新台币，限时下杀一百零七新台币。",
              "kind": "product_claim",
              "fact_ids": ["PROMOTION", "PRICE"]
            }
          ]
        },
        {
          "stage": "cta",
          "focus": "自然购买引导",
          "sentences": [
            {
              "display_text": "这双鞋最值得关注的是足弓支撑、静音防滑和轻便好打理。",
              "spoken_text": "这双鞋最值得关注的是足弓支撑、静音防滑和轻便好打理。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "大家可以根据自己喜欢的颜色和合适的尺码来选择，合适再下单。",
              "spoken_text": "大家可以根据自己喜欢的颜色和合适的尺码来选择，合适再下单。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        }
      ]
    }
  ],
